package metric

import (
	"math"
	"testing"

	"github.com/kbukum/gokit/bench"
)

// Constants generated by Python 3.11.6, sacrebleu 2.4.3 and rouge-score 0.1.2.
func TestPinnedTextReferences(t *testing.T) {
	t.Parallel()
	cases := []struct {
		name     string
		hyp, ref []string
		bleu     float64
		rouge    [3]float64
	}{
		{"empty", []string{""}, []string{""}, 0, [3]float64{}},
		{"one", []string{"hello"}, []string{"hello"}, 0, [3]float64{1, 0, 1}},
		{"exact", []string{"the cat is sitting on the mat"}, []string{"the cat is sitting on the mat"}, 1, [3]float64{1, 1, 1}},
		{"mixed", []string{"the cat sat on the mat", "a quick brown fox jumps"}, []string{"the cat is on the mat", "the quick brown fox jumped"}, .3277850848803996, [3]float64{.7166666666666667, .55, .7166666666666667}},
		{"punctuation", []string{"Hello, world! 1,000.5 & test"}, []string{"Hello world 1,000.5 & test"}, .2777619034011791, [3]float64{1, 1, 1}},
		{"asymmetric", []string{"one two"}, []string{"one two three four"}, 0, [3]float64{2.0 / 3, .5, 2.0 / 3}},
		{"entities", []string{"A &amp;quot;word&amp;quot; stays the same."}, []string{"A &quot;word&quot; stays the same."}, .23462350320527997, [3]float64{.8750000000000001, .5714285714285715, .8750000000000001}},
		{"repeated", []string{"a b a b"}, []string{"a b b a"}, .45180100180492266, [3]float64{1, 2.0 / 3, .75}},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			t.Parallel()
			var samples []bench.ScoredSample[string]
			for i, hyp := range tc.hyp {
				samples = append(samples, bench.ScoredSample[string]{Sample: bench.Sample[string]{Label: tc.ref[i]}, Prediction: bench.Prediction[string]{Label: hyp}})
			}
			metrics := []Metric[string]{BLEU(), ROUGE1(), ROUGE2(), ROUGEL()}
			expected := []float64{tc.bleu, tc.rouge[0], tc.rouge[1], tc.rouge[2]}
			for i, m := range metrics {
				acc := m.(Streaming[string]).NewAccumulator()
				for _, s := range samples {
					if err := acc.Add(s); err != nil {
						t.Fatal(err)
					}
				}
				for _, got := range []Result{m.Compute(samples), acc.Result()} {
					if math.Abs(got.Value-expected[i]) > 1e-9 {
						t.Fatalf("%s = %.15g, want %.15g", got.Name, got.Value, expected[i])
					}
					if tc.name == "asymmetric" && i > 0 {
						recall := .5
						if i == 2 {
							recall = 1.0 / 3
						}
						if math.Abs(got.Values["precision"]-1) > 1e-9 || math.Abs(got.Values["recall"]-recall) > 1e-9 {
							t.Fatalf("%s precision/recall = %v", got.Name, got.Values)
						}
					}
				}
			}
		})
	}
}
